WITH flattened AS (SELECT id, customer_id, created_at, pos + 1 AS item_no, elem.qty, elem.price, elem.promo FROM carts LATERAL VIEW OUTER POSEXPLODE(items) x AS pos, elem) SELECT CASE WHEN qty >= 5 THEN 'HIGH' ELSE 'LOW' END AS qty_tier, DATE_TRUNC('DAY', created_at) AS activity_day, CASE WHEN price >= 214 THEN 'HIGH' ELSE 'LOW' END AS price_tier, COUNT(DISTINCT promo) AS distinct_promos, ROUND(SUM(price) / NULLIF(COUNT(CASE WHEN promo = 'SPRING10' THEN 1 END), 0), 2) AS price_per_spring10, ROUND(AVG(price), 2) AS avg_price, COUNT(CASE WHEN promo = 'VIP' THEN 1 END) AS vip_count FROM flattened GROUP BY 1, 2, 3 ORDER BY distinct_promos DESC
